477	  private _writeMatchStartKeyframe(
478	    currentObject: ContactTheatreObject,
479	    currentSequence: ContactTheatreSequence,
480	    previousEndValues: ContactTheatreValue,
481	  ): void {
482	    const previousPosition = currentSequence.position;
483	    const scrub = TheatreStudioService.createScrub<
484	      ContactTheatreValue,
485	      ContactTheatreProps
486	    >();
487	    currentSequence.position = 0;
488	    scrub.capture(({ set }) => {
489	      set(currentObject.props, previousEndValues);
490	    });
491	    scrub.commit();
492	    currentSequence.position = previousPosition;
493	  }
