283	  private _resolveMainWhyShowcaseProgress(
284	    sceneKey: MainSceneSectionKey,
285	    progress: number,
286	  ): number {
287	    if (sceneKey === "whyus") {
288	      return Helpers.clamp01(progress);
289	    }
290	
291	    const sceneOrder: readonly MainSceneSectionKey[] = [
292	      "intro",
293	      "hero",
294	      "story",
295	      "who",
296	      "whyus",
297	      "services",
298	      "works",
299	      "worksDetail",
300	      "worksFinal",
301	      "client",
302	      "contact",
303	    ];
304	    const currentIndex = sceneOrder.indexOf(sceneKey);
305	    const whyIndex = sceneOrder.indexOf("whyus");
306	    if (currentIndex > whyIndex) {
307	      return 1;
308	    }
