322	  private _resolveAboutHeroSloganKeywordStep(
323	    sceneKey: AboutSceneSectionKey,
324	    progress: number,
325	  ): number {
326	    if (sceneKey !== "heroSlogan") return 0;
327	    const keywordCount = Math.max(ABOUT_HERO_SLOGAN.keywordCount, 1);
328	    const clampedProgress = Helpers.clamp01(progress);
329	    const windowedProgress = this._resolveAboutHeroSloganKeywordProgress(
330	      clampedProgress,
331	    );
332	    return Math.min(
333	      Math.floor(windowedProgress * keywordCount),
334	      keywordCount - 1,
335	    );
336	  }
337	
338	  private _resolveAboutHeroSloganKeywordProgress(progress: number): number {
339	    const start = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowStart);
340	    const end = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowEnd);
341	    if (end <= start) return progress;
342	    if (progress <= start) return 0;
343	    if (progress >= end) return 1;
344	    return (progress - start) / (end - start);
345	  }
