358	  private _applyAboutHeroSloganKeywordStep(
359	    viewport: HTMLElement,
360	    track: HTMLElement,
361	    step: number,
362	    shouldAnimate: boolean,
363	    gsap: GsapGlobal | null,
364	  ): void {
365	    const keywordHeight = this._resolveAboutHeroSloganKeywordHeight(track, step);
366	    const keywordWidth = this._resolveAboutHeroSloganKeywordWidth(track, step);
367	    const keywords = this._resolveAboutHeroSloganKeywordElements(track);
368	    const y = -(keywordHeight * step);
369	    if (!shouldAnimate || !gsap) {
370	      track.style.transform = `translate3d(0, ${y}px, 0)`;
371	      viewport.style.width = `${keywordWidth}px`;
372	      this._applyAboutHeroSloganKeywordVisualState(keywords, step);
373	      return;
374	    }
375	    gsap.killTweensOf?.(track);
376	    gsap.killTweensOf?.(viewport);
377	    gsap.to(track, {
378	      y,
379	      duration: ABOUT_HERO_SLOGAN.duration,
380	      ease: ABOUT_HERO_SLOGAN.ease,
381	      overwrite: true,
382	    });
383	    gsap.to(viewport, {
384	      width: keywordWidth,
385	      duration: ABOUT_HERO_SLOGAN.duration,
386	      ease: ABOUT_HERO_SLOGAN.ease,
387	      overwrite: true,
388	    });
389	    this._animateAboutHeroSloganKeywordVisualState(keywords, step, gsap);
390	  }
