480	  private _applyMainWhyShowcaseState(
481	    titleLayers: readonly HTMLElement[],
482	    ring: HTMLElement,
483	    cards: readonly HTMLElement[],
484	    progress: number,
485	  ): void {
486	    const cardCount = Math.max(cards.length, 1);
487	    const spawnProgress = this._easeOutCubic(
488	      Helpers.remap01(progress, 0, MAIN_WHY_SHOWCASE.spawnEnd),
489	    );
490	    const mergeProgress = this._easeInOutCubic(
491	      Helpers.remap01(
492	        progress,
493	        MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
494	        MAIN_WHY_SHOWCASE.mergeEnd,
495	      ),
496	    );
497	    const scatterProgress = this._easeOutCubic(
498	      Helpers.remap01(
499	        progress,
500	        MAIN_WHY_SHOWCASE.mergeEnd,
501	        MAIN_WHY_SHOWCASE.scatterEnd,
502	      ),
503	    );
504	
505	    const titleRevealOpacity = Helpers.lerp(
506	      MAIN_WHY_SHOWCASE.titleOpacityStart,
507	      MAIN_WHY_SHOWCASE.titleOpacityEnd,
508	      spawnProgress,
509	    );
510	    const titleOpacity = Helpers.lerp(
511	      titleRevealOpacity,
512	      MAIN_WHY_SHOWCASE.titleExitOpacity,
513	      scatterProgress,
514	    );
515	    const titlePeakScale = Helpers.lerp(
516	      MAIN_WHY_SHOWCASE.titleScaleStart,
517	      MAIN_WHY_SHOWCASE.titleScalePeak,
518	      Math.max(spawnProgress, mergeProgress),
519	    );
520	    const titleScale = Helpers.lerp(
521	      titlePeakScale,
522	      MAIN_WHY_SHOWCASE.titleScaleEnd,
523	      scatterProgress,
524	    );
525	    const titleY = Helpers.lerp(
526	      MAIN_WHY_SHOWCASE.titleYOffsetPx,
527	      0,
528	      spawnProgress,
529	    ) + Helpers.lerp(0, MAIN_WHY_SHOWCASE.titleExitYOffsetPx, scatterProgress);
530	
531	    const titleTransform = `translate3d(0, ${titleY}px, 0) scale(${titleScale})`;
532	    titleLayers.forEach((titleLayer) => {
533	      titleLayer.style.opacity = String(titleOpacity);
534	      titleLayer.style.transform = titleTransform;
535	    });
536	
537	    const ringOpacity =
538	      MAIN_WHY_SHOWCASE.ringOpacityMax * Math.max(spawnProgress, mergeProgress);
539	    const ringScale = Helpers.lerp(
540	      MAIN_WHY_SHOWCASE.ringScaleStart,
541	      MAIN_WHY_SHOWCASE.ringScaleEnd,
542	      Math.max(spawnProgress, scatterProgress),
543	    );
544	    ring.style.opacity = String(ringOpacity);
545	    ring.style.transform = `translate3d(-50%, -50%, 0) scale(${ringScale})`;
546	
547	    cards.forEach((card, index) => {
548	      const pose = MAIN_WHY_SHOWCASE.cardPoses[index];
549	      if (!pose) return;
550	      const revealStart =
551	        Helpers.lerp(
552	          MAIN_WHY_SHOWCASE.cardRevealWindowStart,
553	          MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
554	          index / cardCount,
555	        );
556	      const revealEnd =
557	        Helpers.lerp(
558	          MAIN_WHY_SHOWCASE.cardRevealWindowStart,
559	          MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
560	          (index + 1) / cardCount,
561	        );
562	      const cardRevealProgress = this._easeOutCubic(
563	        Helpers.remap01(progress, revealStart, revealEnd),
564	      );
565	      const orbitX =
566	        Math.cos(Helpers.degToRad(pose.orbitAngleDeg)) * pose.orbitRadiusVmin;
567	      const orbitY =
568	        Math.sin(Helpers.degToRad(pose.orbitAngleDeg)) *
569	        pose.orbitRadiusVmin *
570	        MAIN_WHY_SHOWCASE.orbitVerticalScale;
571	      const orbitRotate = pose.orbitRotateDeg;
572	      const revealScale =
573	        pose.scale *
574	        this._easeOutBack(
575	          cardRevealProgress,
576	          MAIN_WHY_SHOWCASE.cardRevealOvershoot,
577	        );
578	
579	      const mergedX = Helpers.lerp(orbitX, pose.stackXvmin, mergeProgress);
580	      const mergedY = Helpers.lerp(orbitY, pose.stackYvmin, mergeProgress);
581	      const mergedRotate = Helpers.lerp(
582	        orbitRotate,
583	        pose.stackRotateDeg,
584	        mergeProgress,
585	      );
586	      const mergedScale = Helpers.lerp(
587	        revealScale,
588	        pose.scale * MAIN_WHY_SHOWCASE.cardMergeScaleFactor,
589	        mergeProgress,
590	      );
591	
592	      const x = Helpers.lerp(mergedX, pose.scatterXvmin, scatterProgress);
593	      const y = Helpers.lerp(mergedY, pose.scatterYvmin, scatterProgress);
594	      const rotate = Helpers.lerp(
595	        mergedRotate,
596	        pose.scatterRotateDeg,
597	        scatterProgress,
598	      );
599	      const scale = Helpers.lerp(
600	        mergedScale,
601	        pose.scale * MAIN_WHY_SHOWCASE.cardScatterScaleFactor,
602	        scatterProgress,
603	      );
604	      const opacity = Helpers.lerp(
605	        Helpers.lerp(
606	          MAIN_WHY_SHOWCASE.cardOpacityStart,
607	          MAIN_WHY_SHOWCASE.cardOpacityEnd,
608	          cardRevealProgress,
609	        ),
610	        MAIN_WHY_SHOWCASE.cardScatterOpacity,
611	        scatterProgress,
612	      );
613	
614	      card.style.setProperty("--about-who-card-x", `${x}vmin`);
615	      card.style.setProperty("--about-who-card-y", `${y}vmin`);
616	      card.style.setProperty("--about-who-card-rotate", `${rotate}deg`);
617	      card.style.setProperty("--about-who-card-scale", String(scale));
618	      card.style.setProperty("--about-who-card-opacity", String(opacity));
619	      card.style.setProperty("--about-who-card-z", String(pose.zIndex));
620	    });
621	  }
622	
623	  private _easeOutCubic(value: number): number {
624	    const clampedValue = Helpers.clamp01(value);
625	    return 1 - Math.pow(1 - clampedValue, 3);
626	  }
627	
628	  private _easeOutBack(value: number, overshoot: number): number {
629	    const clampedValue = Helpers.clamp01(value);
630	    const nextValue = clampedValue - 1;
631	    return (
632	      1 +
633	      (overshoot + 1) * Math.pow(nextValue, 3) +
634	      overshoot * Math.pow(nextValue, 2)
635	    );
636	  }
637	
638	  private _easeInOutCubic(value: number): number {
639	    const clampedValue = Helpers.clamp01(value);
640	    if (clampedValue < 0.5) {
641	      return 4 * clampedValue * clampedValue * clampedValue;
642	    }
643	    const nextValue = -2 * clampedValue + 2;
644	    return 1 - Math.pow(nextValue, 3) / 2;
645	  }
646	
647	  private _applyAboutHeroSloganKeywordVisualState(
648	    keywords: readonly HTMLElement[],
649	    activeStep: number,
650	  ): void {
651	    keywords.forEach((keyword, index) => {
652	      const isActive = index === activeStep;
653	      keyword.style.opacity = String(
654	        isActive
655	          ? ABOUT_HERO_SLOGAN.activeOpacity
656	          : ABOUT_HERO_SLOGAN.inactiveOpacity,
657	      );
658	      keyword.style.textShadow = isActive
659	        ? ABOUT_HERO_SLOGAN.activeTextShadow
660	        : ABOUT_HERO_SLOGAN.inactiveTextShadow;
661	    });
662	  }
663	
664	  private _animateAboutHeroSloganKeywordVisualState(
665	    keywords: readonly HTMLElement[],
666	    activeStep: number,
667	    gsap: GsapGlobal,
668	  ): void {
669	    keywords.forEach((keyword, index) => {
670	      const isActive = index === activeStep;
671	      gsap.killTweensOf?.(keyword);
672	      gsap.to(keyword, {
673	        opacity: isActive
674	          ? ABOUT_HERO_SLOGAN.activeOpacity
675	          : ABOUT_HERO_SLOGAN.inactiveOpacity,
676	        textShadow: isActive
677	          ? ABOUT_HERO_SLOGAN.activeTextShadow
678	          : ABOUT_HERO_SLOGAN.inactiveTextShadow,
679	        duration: ABOUT_HERO_SLOGAN.duration,
680	        ease: ABOUT_HERO_SLOGAN.ease,
681	        overwrite: true,
682	      });
683	    });
684	  }
