1041	  private _syncContactDomMotion(state: ContactDomState | null): void {
1042	    this._clearContactMotionTimers();
1043	    const blocks = this._resolveContactRevealBlocks();
1044	    const successBlocks = this._resolveContactSuccessBlocks();
1045	    const successTextNodes = this._resolveContactSuccessTextNodes();
